select count(*)
from chat_room_user
where room_id = #{room_id}
and user_id = #{user_id}

SELECT m.message_id, m.room_id, m.sender_id, CASE WHEN m.sender_id = #{systemId} THEN 'SYSTEM' ELSE u.webuser_name END AS senderName, m.content, m.created_at,
/* ✅ 내 메시지일 때만: 아직 안 읽은 사람 수 계산 */ CASE WHEN m.sender_id = #{systemId} THEN 0 WHEN m.sender_id = #{userId} THEN ( SELECT COUNT(*) FROM chat_room_user cru WHERE cru.room_id = m.room_id AND cru.user_id <> m.sender_id AND NVL(cru.last_read_message_id,0) < m.message_id ) ELSE 0 END AS read_count
FROM chat_message m LEFT JOIN webuser u ON m.sender_id = u.webuser_id WHERE m.room_id = #{roomId} ORDER BY m.message_id

SELECT webuser_name
FROM webuser
WHERE webuser_id = #{userId}

SELECT user_id
FROM chat_room_user
WHERE room_id = #{roomId}
AND user_id != #{userId}

select count(*)
from chat_room_user
where room_id = #{roomId}

SELECT NVL(MAX(message_id), 0)
FROM chat_message
WHERE room_id = #{roomId}

