mapper.select:
SELECT CASE WHEN r.room_type = 'one' THEN opp.webuser_name ELSE r.room_name END AS display_name FROM chat_room r JOIN chat_room_user ru ON ru.room_id = r.room_id AND ru.user_id = #{userId}
LEFT JOIN ( SELECT room_id, COUNT(*) AS user_count FROM chat_room_user GROUP BY room_id ) cnt ON cnt.room_id = r.room_id
-- ✅ 1:1일 때만 상대 조인 (group이면 ru2/opp가 안 붙어서 1줄만 나옴) LEFT JOIN chat_room_user ru2 ON ru2.room_id = r.room_id AND r.room_type = 'one' AND ru2.user_id != #{userId} LEFT JOIN webuser opp ON opp.webuser_id = ru2.user_id
WHERE r.room_id = #{roomId}
